		assert.throws(() => {
			ruleTester.run("uses-start-end", usesStartEndRule, {
				valid: [],
				invalid: [{ code: "var a = b * (c + d) / e;", errors: 1 }],
			});
		}, "Use node.range[1] instead of node.end");
		assert.throws(() => {
			ruleTester.run("uses-start-end", usesStartEndRule, {
				valid: [],
